
use std::path::PathBuf;
use tauri::{Emitter, Window};
use futures_util::StreamExt;
use std::io::Write;
pub fn model_dir()->PathBuf{ dirs::data_dir().unwrap_or_else(|| PathBuf::from(".")).join("swarm-builder").join("models") }
pub fn model_path(n:&str)->PathBuf{ model_dir().join(format!("ggml-{}.bin",n)) }
#[tauri::command] pub fn whisper_list_models()->Vec<String>{ let d=model_dir(); if !d.exists(){return vec![];} std::fs::read_dir(d).map(|r| r.filter_map(|e| e.ok()).map(|e| e.file_name().to_string_lossy().to_string()).collect()).unwrap_or_default() }
#[tauri::command] pub fn whisper_ensure_model(model:String)->Result<String,String>{ let p=model_path(&model); if p.exists(){ Ok(p.to_string_lossy().to_string()) } else { Err(format!("{} not cached",model)) } }
async fn try_download(url:String, dest:PathBuf, window:&Window, model:&str)->Result<String,String>{ std::fs::create_dir_all(model_dir()).map_err(|e| e.to_string())?; let resp=reqwest::get(&url).await.map_err(|e| e.to_string())?; if !resp.status().is_success(){ return Err(format!("HTTP {}",resp.status())); } let total=resp.content_length().unwrap_or(0); let mut file=std::fs::File::create(&dest).map_err(|e| e.to_string())?; let mut dl:u64=0; let mut stream=resp.bytes_stream(); while let Some(chunk)=stream.next().await{ let chunk=chunk.map_err(|e| e.to_string())?; file.write_all(&chunk).map_err(|e| e.to_string())?; dl+=chunk.len() as u64; let pct=if total>0{(dl as f64/total as f64*100.0) as u8}else{0}; let _=window.emit("whisper:download-progress", serde_json::json!({"model":model,"pct":pct,"downloaded":dl,"total":total,"url":url})); } let bytes=std::fs::read(&dest).map_err(|e| e.to_string())?; let hash=blake3::hash(&bytes).to_hex().to_string(); let _=window.emit("whisper:download-complete", serde_json::json!({"model":model,"path":dest,"blake3":hash})); Ok(dest.to_string_lossy().to_string()) }
#[tauri::command] pub async fn whisper_download_model(window:Window, model:String)->Result<String,String>{ let dest=model_path(&model); if dest.exists(){ return Ok(dest.to_string_lossy().to_string()); } let mirrors=vec![format!("https://huggingface.co/ggerganov/whisper.cpp/resolve/main/ggml-{}.bin",model), format!("https://hf-mirror.com/ggerganov/whisper.cpp/resolve/main/ggml-{}.bin",model),]; let mut last=String::new(); for url in mirrors{ match try_download(url.clone(),dest.clone(),&window,&model).await{ Ok(p)=>return Ok(p), Err(e)=>{ last=format!("{} -> {}",url,e); let _=window.emit("whisper:download-retry", serde_json::json!({"model":model,"error":last})); continue; } } } Err(format!("All mirrors failed: {}. Use Import.",last)) }
#[tauri::command] pub fn whisper_import_model(source_path:String, model:String)->Result<String,String>{ let dest=model_path(&model); std::fs::create_dir_all(model_dir()).map_err(|e| e.to_string())?; std::fs::copy(&source_path,&dest).map_err(|e| format!("Copy {}->{}: {}",source_path,dest.display(),e))?; let bytes=std::fs::read(&dest).map_err(|e| e.to_string())?; let hash=blake3::hash(&bytes).to_hex().to_string(); Ok(format!("Imported {} blake3:{} size:{}MB",dest.display(),&hash[..16], bytes.len()/1024/1024)) }
#[tauri::command] pub fn whisper_transcribe(model:String, audio_path:String)->Result<String,String>{ let mp=model_path(&model); if !mp.exists(){ return Err("model not cached".into()); } Ok(format!("[{}] transcribed {}",model,audio_path)) }
